float toVolts(int reading, int maximum, float supply) {
  return reading * supply / maximum;
}
void setup() {
  Serial.begin(9600);
  float voltage = toVolts(512, 1023, 5.0);
  Serial.print("Approximate voltage: ");
  Serial.println(voltage);
}
void loop() {}

