const int ledPin = 9;
const unsigned long interval = 500;
unsigned long previous = 0;
bool ledOn = false;
void setup() { pinMode(ledPin, OUTPUT); }
void loop() {
  unsigned long current = millis();
  if (current - previous >= interval) {
    previous = current;
    ledOn = !ledOn;
    digitalWrite(ledPin, ledOn ? HIGH : LOW);
  }
}

