void setup() {
  Serial.begin(115200);
  Serial.println("Send h for help or s for status");
}
void loop() {
  if (Serial.available() > 0) {
    char command = Serial.read();
    switch (command) {
      case 'h':
        Serial.println("Commands: h=help, s=status");
        break;
      case 's':
        Serial.println("Ready");
        break;
      case '\n':
      case '\r':
        break;
      default:
        Serial.println("Unknown command");
        break;
    }
  }
}

const int ledPin = 9;
const unsigned long durations[] = {100, 100, 100, 700};
int phase = 0;
unsigned long changedAt = 0;
void setup() {
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, HIGH);
}
void loop() {
  unsigned long current = millis();
  if (current - changedAt >= durations[phase]) {
    changedAt = current;
    phase = (phase + 1) % 4;
    digitalWrite(ledPin, phase % 2 == 0 ? HIGH : LOW);
  }
}

