const int buttonPin = 2;
const int ledPin = 9;
int previous = HIGH;
int stable = HIGH;
bool ledOn = false;
unsigned long changedAt = 0;
void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
}
void loop() {
  int reading = digitalRead(buttonPin);
  if (reading != previous) changedAt = millis();
  if (millis() - changedAt >= 30 && reading != stable) {
    stable = reading;
    if (stable == LOW) ledOn = !ledOn;
  }
  previous = reading;
  digitalWrite(ledPin, ledOn ? HIGH : LOW);
}

void flash(int duration) {
  digitalWrite(9, HIGH);
  delay(duration);
  digitalWrite(9, LOW);
  delay(150);
}
void setup() { pinMode(9, OUTPUT); }
void loop() {
  for (int count = 0; count < 3; count++) flash(150);
  delay(300);
  for (int count = 0; count < 3; count++) flash(450);
  delay(300);
  for (int count = 0; count < 3; count++) flash(150);
  delay(900);
}
